#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/uniclogs/encoder.h>
// pydoc.h is automatically generated in the build directory
#include <encoder_pydoc.h>

void bind_encoder(py::module& m)
{

    using encoder = ::gr::uniclogs::encoder;


    py::class_<encoder, std::shared_ptr<encoder>>(m, "encoder", D(encoder))

        .def(py::init<>(), D(encoder, encoder, 0))
        .def(py::init<gr::uniclogs::encoder const&>(),
             py::arg("arg0"),
             D(encoder, encoder, 1))


        .def("unique_id", &encoder::unique_id, D(encoder, unique_id))


        .def("encode", &encoder::encode, py::arg("pdu"), D(encoder, encode))

        ;
}
